sys_ws_operation.operation_script:
// Role: receives one file for one mapping and hands it to CPMEvidence, which does all the checks.
//       The browser sends the raw file; its declared type and name travel as query parameters.
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
  var file = {
    name: String(request.queryParams.file_name || '').replace(/[\\\/]/g, '_').substring(0, 100),
    type: String(request.queryParams.content_type || '').toLowerCase(),
    size: parseInt(request.getHeader('content-length'), 10) || 0
  };
  gs.info("--- REST API TEST --- Mapping SysID called: " + pathParams.sys_id);
  var result = new CPMEvidence().receive(request.pathParams.mapping, file, request.body.dataStream);
  response.setStatus(result.status);
  response.setBody(result.body);
})(request, response);
